exercises.solution:
package main

import (
    "fmt"
    "sort"
    "sync"
)

func main() {
    ch := make(chan string, 2)
    var wg sync.WaitGroup

    wg.Add(2)
    go func() {
        defer wg.Done()
        ch <- "hello"
    }()
    go func() {
        defer wg.Done()
        ch <- "world"
    }()

    go func() {
        wg.Wait()
        close(ch)
    }()

    var msgs []string
    for msg := range ch {
        msgs = append(msgs, msg)
    }
    sort.Strings(msgs)
    for _, msg := range msgs {
        fmt.Println(msg)
    }
}

