exercises.solution:
package main

import (
    "fmt"
    "sync"
)

func main() {
    var wg sync.WaitGroup
    results := make([]int, 3)

    for i := 1; i <= 3; i++ {
        wg.Add(1)
        go func(n int) {
            defer wg.Done()
            results[n-1] = n
        }(i)
    }

    wg.Wait()
    for _, n := range results {
        fmt.Println(n)
    }
    fmt.Println("done")
}
